<x-layouts::app title="Cheque Calendar"><div class="flex h-16 items-center justify-between border-b bg-white px-6"><div><h1 class="text-lg font-bold">Cheque Calendar</h1><p class="text-xs text-black">Monthly maturity calendar</p></div><form class="flex gap-2"><select name="month">@foreach(range(1,12) as $m)<option @selected($month===$m) value="{{ $m }}">{{ \Carbon\Carbon::create()->month($m)->format('F') }}</option>@endforeach</select><input type="number" name="year" value="{{ $year }}" class="w-24"><button class="rounded-lg bg-blue-600 px-4 text-xs font-bold text-white">Go</button></form></div><div class="flex-1 overflow-y-auto bg-slate-50 p-6"><div class="grid grid-cols-7 overflow-hidden rounded-2xl border bg-white shadow-sm">@foreach(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as $d)<div class="border-b bg-slate-50 p-3 text-center text-[10px] font-bold uppercase text-black">{{ $d }}</div>@endforeach @php($first=\Carbon\Carbon::create($year,$month,1)) @for($i=0;$i<$first->dayOfWeek;$i++)<div class="min-h-32 border-b border-r bg-slate-50/40"></div>@endfor @for($day=1;$day<=$first->daysInMonth;$day++)<div class="min-h-32 border-b border-r p-2"><b class="text-xs">{{ $day }}</b><div class="mt-2 space-y-1">@foreach($cheques->get($day,collect()) as $c)<a href="{{ route('cheques.show',$c) }}" class="block truncate rounded-md px-2 py-1 text-[9px] font-bold text-white {{ $c->display_status==='returned'?'bg-red-600':($c->display_status==='passed'?'bg-emerald-600':($c->cheque_type==='issued'?'bg-purple-600':'bg-blue-600')) }}">{{ $c->cheque_number }} · {{ number_format($c->amount) }}</a>@endforeach</div></div>@endfor</div></div></x-layouts::app>
